mapper.select:
SELECT DISTINCT pp.PORTFOLIO_ID AS portfolioId, pp.PORTFOLIO_NAME AS portfolioName, pp.VDATE AS vdate, pp.MDATE AS mdate FROM PTL_PORTFOLIO pp LEFT JOIN PTL_SEC_ACCT psa ON psa.PORTFOLIO_ID = pp.PORTFOLIO_ID LEFT JOIN PTL_CAPACCT_INFO pci ON pci.PORTFOLIO_ID = pp.PORTFOLIO_ID WHERE pci.ACCT_NO in (SELECT DISTINCT B.ACCT_NO FROM PTL_CAPACCT_INFO B WHERE B.PORTFOLIO_ID = #{portfolioId} AND B.ACCT_TYPE = #{capacctType} AND B.CCY = #{ccy})
and psa.ACCT_NO = #{secAcctId,jdbcType=VARCHAR}
AND PP.PORTFOLIO_ID != #{portfolioId,jdbcType=VARCHAR} AND pp.INVEST_YESORNO='Y' AND pp.MDATE >=TO_DATE(#{tradeDate},'yyyy-MM-dd') AND pp.VDATE <=TO_DATE(#{tradeDate},'yyyy-MM-dd')
